-- Second, independently-authored eval dataset for generalization testing (docs/QWEN_TUNING.md
-- Follow-up: does the tuned prompt/config only work on BATON Scenario Dataset v1's specific
-- domains, or does it generalize?). Same volume (50 scenarios / 350 replies) but different
-- domains and mostly non-date branch conditions (price tiers, capacity, approval levels) to
-- avoid re-testing the same date-arithmetic failure mode DateRangeGuardrail already targets.

INSERT INTO eval_datasets (name, task_type, version, description, created_at)
VALUES ('BATON Scenario Dataset v2 (generalization) (2.0.0)', 'REPLY_CLASSIFICATION', 1, 'Held-out generalization dataset, different domains than v1: 50 scenarios, 350 reply cases.', CURRENT_TIMESTAMP);

